The affine Yokonuma-Hecke algebra, denoted by $\widehat{Y}_{r,n}(q)$, is an $\mathcal{R}$-associative algebra generated by the elements $t_{1},\ldots,t_{n},g_{1},\ldots,g_{n-1},X_{1}^{\pm1},$ in which the generators $t_{1},\ldots,t_{n},g_{1},$ $\ldots,g_{n-1}$ satisfy the following relations:
\begin{align}
g_ig_j&=g_jg_i \qquad \qquad\qquad\quad\hspace{0.3cm}\mbox{for all $i,j=1,\ldots,n-1$ such that $\vert i-j\vert \geq 2$;}\label{rel-def-Y1}\\[0.1em]
g_ig_{i+1}g_i&=g_{i+1}g_ig_{i+1} \qquad \quad\qquad\hspace{0.05cm}\mbox{for all $i=1,\ldots,n-2$;}\label{rel-def-Y2}\\[0.1em]
t_it_j&=t_jt_i \qquad\qquad\qquad\qquad  \mbox{for all $i,j=1,\ldots,n$;}\label{rel-def-Y3}\\[0.1em]
g_it_j&=t_{s_i(j)}g_i \quad \quad\qquad\qquad\hspace{0.25cm}\mbox{for all $i=1,\ldots,n-1$ and $j=1,\ldots,n$;}\label{rel-def-Y4}\\[0.1em]
t_i^r&=1 \quad \qquad\qquad\qquad\qquad\mbox{for all $i=1,\ldots,n$;}\label{rel-def-Y5}\\[0.2em]
g_{i}^{2}&=q+(q-1)e_{i}g_{i} \qquad \hspace{0.48cm}\mbox{for all $i=1,\ldots,n-1$;}\label{rel-def-Y6}
\end{align}
where $s_{i}$ is the transposition $(i,i+1)$, and for each $1\leq i\leq n-1$,
$$e_{i} :=\frac{1}{r}\sum\limits_{s=0}^{r-1}t_{i}^{s}t_{i+1}^{-s},$$
together with the following relations concerning the generators $X_{1}^{\pm1}$:
\begin{align}
X_{1}X_{1}^{-1}&=X_{1}^{-1}X_{1}=1;\label{rel-def-Y7}\\[0.1em]
g_{1}X_{1}g_{1}X_{1}&=X_{1}g_{1}X_{1}g_{1};\label{rel-def-Y8}\\[0.1em]
g_{i}X_{1}&=X_{1}g_{i} \qquad \qquad \quad\mbox{for all $i=2,\ldots,n-1$;}\label{rel-def-Y9}\\[0.1em]
t_{j}X_{1}&=X_{1}t_{j} \qquad \qquad\quad\mbox{for all $j=1,\ldots,n$;}\label{rel-def-Y10}
\end{align}

\begin{align}
g_ig_j&=g_jg_i \qquad \qquad\qquad\quad\hspace{0.3cm}\mbox{for all $i,j=1,\ldots,n-1$ such that $\vert i-j\vert \geq 2$;}\label{rel-def-Y1}\\[0.1em]
g_ig_{i+1}g_i&=g_{i+1}g_ig_{i+1} \qquad \quad\qquad\hspace{0.05cm}\mbox{for all $i=1,\ldots,n-2$;}\label{rel-def-Y2}\\[0.1em]
t_it_j&=t_jt_i \qquad\qquad\qquad\qquad  \mbox{for all $i,j=1,\ldots,n$;}\label{rel-def-Y3}\\[0.1em]
g_it_j&=t_{s_i(j)}g_i \quad \quad\qquad\qquad\hspace{0.25cm}\mbox{for all $i=1,\ldots,n-1$ and $j=1,\ldots,n$;}\label{rel-def-Y4}\\[0.1em]
t_i^r&=1 \quad \qquad\qquad\qquad\qquad\mbox{for all $i=1,\ldots,n$;}\label{rel-def-Y5}\\[0.2em]
